223	    /// Renders the given bytes into an image buffer.
224	    pub fn render_single_frame(
225	        &self,
226	        bytes: &[u8],
227	        scale_factor: f32,
228	    ) -> Result<Arc<RenderImage>, usvg::Error> {
229	        let svg = self.parse_svg(bytes)?;
230	        self.render_parsed(&svg, scale_factor)
231	    }
