233	    pub(crate) fn render_alpha_mask(
234	        &self,
235	        params: &RenderSvgParams,
236	        bytes: Option<&[u8]>,
237	    ) -> Result<Option<(Size<DevicePixels>, Vec<u8>)>> {
238	        anyhow::ensure!(!params.size.is_zero(), "can't render at a zero size");
239	
240	        let render_pixmap = |bytes| {
241	            let pixmap = self.render_pixmap(bytes, SvgSize::Size(params.size))?;
242	
243	            // Convert the pixmap's pixels into an alpha mask.
244	            let size = Size::new(
245	                DevicePixels(pixmap.width() as i32),
246	                DevicePixels(pixmap.height() as i32),
247	            );
248	            let alpha_mask = pixmap
249	                .pixels()
250	                .iter()
251	                .map(|p| p.alpha())
252	                .collect::<Vec<_>>();
253	
254	            Ok(Some((size, alpha_mask)))
255	        };
256	
257	        if let Some(bytes) = bytes {
258	            render_pixmap(bytes)
259	        } else if let Some(bytes) = self.asset_source.load(&params.path)? {
260	            render_pixmap(&bytes)
261	        } else {
262	            Ok(None)
263	        }
264	    }
