266	    fn render_pixmap(&self, bytes: &[u8], size: SvgSize) -> Result<Pixmap, usvg::Error> {
267	        let tree = usvg::Tree::from_data(bytes, &self.usvg_options)?;
268	        rasterize_tree(&tree, size)
269	    }
270	}
