272	fn rasterize_tree(tree: &usvg::Tree, size: SvgSize) -> Result<Pixmap, usvg::Error> {
273	    // Cap the size of the rendered pixmap to avoid texture allocation panics
274	    // Related issue: #56466
275	    const MAX_SIZE: f32 = 8192.0;
276	
277	    let svg_size = tree.size();
278	    let (mut width, mut height) = match size {
279	        SvgSize::Size(size) => {
280	            let scale = i32::from(size.width) as f32 / svg_size.width();
281	            (svg_size.width() * scale, svg_size.height() * scale)
282	        }
283	        SvgSize::ExactSize(size) => (i32::from(size.width) as f32, i32::from(size.height) as f32),
284	        SvgSize::ScaleFactor(scale) => (svg_size.width() * scale, svg_size.height() * scale),
285	    };
286	
287	    if width > MAX_SIZE {
288	        log::warn!("Attempted to render pixmap where width ({width}) > MAX_SIZE ({MAX_SIZE})");
289	    }
290	    if height > MAX_SIZE {
291	        log::warn!("Attempted to render pixmap where height ({height}) > MAX_SIZE ({MAX_SIZE})");
292	    }
293	    let scale = (MAX_SIZE / width).min(MAX_SIZE / height).min(1.0);
294	    width *= scale;
295	    height *= scale;
296	
297	    // Render the SVG to a pixmap with the specified width and height.
298	    let mut pixmap = resvg::tiny_skia::Pixmap::new(width as u32, height as u32)
299	        .ok_or(usvg::Error::InvalidSize)?;
300	
301	    let transform = resvg::tiny_skia::Transform::from_scale(
302	        width / svg_size.width(),
303	        height / svg_size.height(),
304	    );
305	
306	    resvg::render(tree, transform, &mut pixmap.as_mut());
307	
308	    Ok(pixmap)
309	}
