750	pub enum ImageCacheError {
751	    /// Some other kind of error occurred
752	    #[error("error: {0}")]
753	    Other(#[from] Arc<anyhow::Error>),
754	    /// An error that occurred while reading the image from disk.
755	    #[error("IO error: {0}")]
