/// Paint a monochrome SVG into the scene for the next frame at the current stacking context.
///
/// This method should only be called as part of the paint phase of element drawing.
pub fn paint_svg(
    &mut self,
    bounds: Bounds<Pixels>,
    path: SharedString,
    mut data: Option<&[u8]>,
    transformation: TransformationMatrix,
    color: Hsla,
    cx: &App,
) -> Result<()> {
    self.invalidator.debug_assert_paint();

    let element_opacity = self.element_opacity();
    let bounds = self.snap_bounds(bounds);

    let params = RenderSvgParams {
        path,
        size: bounds.size.map(|pixels| {
            DevicePixels::from((pixels.0 * SMOOTH_SVG_SCALE_FACTOR).ceil() as i32)
        }),
    };

    let Some(tile) =
        self.sprite_atlas
            .get_or_insert_with(&params.clone().into(), &mut || {
                let Some((size, bytes)) = cx.svg_renderer.render_alpha_mask(&params, data)?
                else {
                    return Ok(None);
                };
                Ok(Some((size, Cow::Owned(bytes))))
            })?
    else {
        return Ok(());
    };
    let content_mask = self.snapped_content_mask();
    let svg_bounds = Bounds {
        origin: bounds.center()
            - Point::new(
                ScaledPixels(tile.bounds.size.width.0 as f32 / SMOOTH_SVG_SCALE_FACTOR / 2.),
                ScaledPixels(tile.bounds.size.height.0 as f32 / SMOOTH_SVG_SCALE_FACTOR / 2.),
            ),
        size: tile
            .bounds
            .size
            .map(|value| ScaledPixels(value.0 as f32 / SMOOTH_SVG_SCALE_FACTOR)),
    };
    let final_bounds = svg_bounds
        .map_origin(|value| ScaledPixels(round_half_toward_zero(value.0)))
        .map_size(|size| size.ceil());

    self.next_frame.scene.insert_primitive(MonochromeSprite {
        order: 0,
        pad: 0,
        bounds: final_bounds,
        content_mask,
        color: color.opacity(element_opacity),
        tile,
        transformation,
    });

    Ok(())
}

/// Paint an image into the scene for the next frame at the current z-index.
/// This method will panic if the frame_index is not valid
///
/// This method should only be called as part of the paint phase of element drawing.
/// Paint an image into `bounds`, positioning and scaling it according to `image_bounds`.
///
/// The visible region rendered is `bounds.intersect(&image_bounds)`, with `corner_radii`
/// applied to `bounds`.
pub fn paint_image(
    &mut self,
    bounds: Bounds<Pixels>,
    image_bounds: Bounds<Pixels>,
    corner_radii: Corners<Pixels>,
    data: Arc<RenderImage>,
    frame_index: usize,
    grayscale: bool,
) -> Result<()> {
    self.invalidator.debug_assert_paint();

    let visible_bounds = bounds.intersect(&image_bounds);
    if visible_bounds.size.width <= Pixels::ZERO || visible_bounds.size.height <= Pixels::ZERO {
        return Ok(());
    }
    if image_bounds.size.width <= Pixels::ZERO || image_bounds.size.height <= Pixels::ZERO {
        return Ok(());
    }

    let params = RenderImageParams {
        image_id: data.id,
        frame_index,
    };

    let tile = self
        .sprite_atlas
        .get_or_insert_with(&params.into(), &mut || {
            Ok(Some((
                data.size(frame_index),
                Cow::Borrowed(
                    data.as_bytes(frame_index)
                        .expect("It's the caller's job to pass a valid frame index"),
                ),
            )))
        })?
        .expect("Callback above only returns Some");

