229	            .insert(hash, gpui::ImageCacheItem::Loading(task.clone()));
230	        self.usages.insert(0, hash);
231	
232	        let entity = window.current_view();
233	        window
234	            .spawn(cx, {
235	                async move |cx| {
236	                    _ = task.await;
237	                    cx.on_next_frame(move |_, cx| {
